 async function woobatMargins(){await ready();const id=527;await ROM_SPRITE_ANIM.prepare([{id,back:false}]);const results=[],envelope=[Infinity,Infinity,-Infinity,-Infinity];let captured=false;for(const [size,foot]of [[128,104],[256,192]]){const c=document.createElement('canvas');c.width=c.height=size;const cx=c.getContext('2d',{willReadFrequently:true});const result=await AmbientAudit.scan(ROM_SPRITE_ANIM.cache[id+'-front'].data,ROM_SPRITE_ANIM.frame,tick=>{cx.clearRect(0,0,size,size);ROM_SPRITE_ANIM.draw(cx,id,false,size/2,foot,64/80,tick,true);const b=ROM_SPRITE_ANIM.alphaBounds(pixels(c),size,size),clipped=!!b&&(b[0]<=0||b[1]<=0||b[2]>=size||b[3]>=size);if(size===256&&b){envelope[0]=Math.min(envelope[0],b[0]-size/2);envelope[1]=Math.min(envelope[1],b[1]-foot);envelope[2]=Math.max(envelope[2],b[2]-size/2);envelope[3]=Math.max(envelope[3],b[3]-foot);}if(size===128&&clipped&&!captured){shot('Woobat: difetto delle ali nel vecchio margine',c);captured=true;}if(size===256&&tick===0)shot('Woobat: ali nel margine completo',c);return {clipped,empty:!b};},{yieldControl:()=>wait(0)});results.push({size,foot,...result});}check(results[0].clipped>0,'Old Woobat crop was not reproduced');check(!results[1].clipped&&!results[1].empty,'Larger Woobat margin still clips');return {old:results[0],candidate:results[1],body:64,envelope};}
