 function matrixMoves049(data,name,visited=new Set()){if(visited.has(name)||!data.progression[name])return [];visited.add(name);const out=new Set([...data.progression[name].moves.map(m=>m.id),165]);for(const item of data.compatibility[name]||[])if(data.machines[item])out.add(data.machines[item]);for(const [from,entries]of Object.entries(data.evolutions))if(entries.some(e=>e.target===name&&(e.method===4&&e.parameter<=data.levelCap||[1,2,3,8].includes(e.method))))for(const id of matrixMoves049(data,from,visited))out.add(id);return [...out];}
